package br.com.alocacao;

import br.com.alocacao.Models.*;
import java.util.*;

final class Html {
    private final OperationService service;
    Html(OperationService service) { this.service = service; }

    String dashboard() {
        AppState s=service.state(); Map<String,Integer> c=service.counts();
        List<Employee> waiting=service.waiting(null);
        List<Post> critical=new ArrayList<>(), partial=new ArrayList<>(), covered=new ArrayList<>();
        for(Post p:service.posts()) switch(service.statusFor(c.get(p.id),p)){case "critical"->critical.add(p);case "partial"->partial.add(p);case "covered"->covered.add(p);}
        long present=s.employees.stream().filter(e->e.status!=EmployeeStatus.ABSENT).count();
        int coverageAllocated=0, coveragePlanned=0; for(Post p:service.posts()){coverageAllocated+=Math.min(c.get(p.id),p.planned);coveragePlanned+=p.planned;}
        int coveragePercent=coveragePlanned==0?0:(int)Math.round(100.0*coverageAllocated/coveragePlanned);
        StringBuilder b=new StringBuilder();
        b.append(heading("Visão do turno","Visão geral da operação","Acompanhe a distribuição da equipe e priorize os postos abaixo do mínimo operacional.", shiftSelector()+link("/pendentes","Revisar pendentes"+(s.pending.isEmpty()?"":" ("+s.pending.size()+")"),"btn btn-quiet")));
        b.append("<section class='metric-grid fade-in delay-1'>")
          .append(metric("Presentes",present+"<span class='metric-note'> / "+s.employees.size()+"</span>","no setor agora",""))
          .append(metric("Aguardando",String.valueOf(waiting.size()),"sem posto definido",""))
          .append(metric("Alocados",String.valueOf(present-waiting.size()),"em um posto","good"))
          .append(metric("Críticos",String.valueOf(critical.size()),"abaixo do mínimo",critical.isEmpty()?"":"critical"))
          .append(metric("Parciais",String.valueOf(partial.size()),"mínimo atingido",""))
          .append(metric("Cobertos",String.valueOf(covered.size()),"no planejado","good")).append("</section>");
        b.append("<div class='dashboard-grid'><section class='fade-in delay-2'><div class='section-head'><h2 class='section-title'>⚠ Atenção necessária</h2><span class='eyebrow danger-text'>").append(critical.size()).append(" ponto(s) de atenção</span></div><div class='attention-list'>");
        List<Post> attention=new ArrayList<>();attention.addAll(critical);attention.addAll(partial);
        for(Post p:attention){int count=c.get(p.id);String st=service.statusFor(count,p);b.append("<div class='attention-card ").append(st).append("'><div class='attention-bar'></div><div class='attention-info'><div class='post-name'>").append(e(p.name)).append("</div><div class='post-sub'>Mínimo ").append(p.minimum).append(" · Planejado ").append(p.planned);if(p.requirement!=null)b.append(" · ").append(e(p.requirement));b.append("</div>").append(statusPill(st));if("critical".equals(st)){int comp=service.compatibleWaiting(p);b.append("<div class='compatible-count'>").append(comp).append(" colaborador(es) compatível(is) disponível(is)</div>").append(link("/aguardando?posto="+u(p.id),"Ver disponíveis →","attention-action"));}b.append("</div><div class='attention-numbers'><div class='count-large'>").append(count).append("<span>/").append(p.planned).append("</span></div><div class='post-sub'>alocados</div></div></div>");}
        if(attention.isEmpty())b.append("<div class='empty-state'><strong>Nenhum ponto exige atenção</strong><p>Todos os postos atingiram pelo menos o planejado operacional.</p></div>");
        b.append("</div></section><section class='coverage-panel fade-in delay-2'><div class='section-head'><h2 class='section-title'>◎ Leitura rápida</h2><span class='status-pill neutral'>").append(service.posts().size()).append(" postos</span></div><div class='coverage-kicker'>Cobertura do planejado</div><div class='coverage-score'>").append(coveragePercent).append("<small>%</small></div><div class='coverage-track'><div class='coverage-fill' style='width:").append(Math.min(100,coveragePercent)).append("%'></div></div><div class='coverage-foot'><span>").append(coverageAllocated).append(" pessoas consideradas</span><span>").append(coveragePlanned).append(" planejadas</span></div></section></div>");
        b.append("<section class='quick-panel fade-in delay-2'><div class='section-head'><h2 class='section-title'>✓ Disponíveis para alocação</h2>").append(link("/aguardando","Ver todos →","section-link")).append("</div>");
        if(waiting.isEmpty())b.append("<div class='empty-state'><strong>Não há pessoas aguardando</strong><p>Todas as pessoas presentes já estão com um posto definido.</p></div>");
        else{b.append("<div class='people-strip'>");for(Employee x:waiting)b.append(personCard(x));b.append("</div>");}b.append("</section>");
        return shell("Dashboard",b.toString(),"/");
    }

    String waiting(String postId) {
        Post filter=service.post(postId);List<Employee> list=service.waiting(postId);
        String title=filter==null?"Aguardando alocação":"Disponíveis para "+filter.name;
        String copy=filter==null?"Estas pessoas já chegaram ao setor e ainda precisam de um posto compatível para começar.":"Colaboradores presentes com habilidade compatível para atuar em "+filter.name+".";
        String action=filter==null?"<span class='status-pill neutral'>"+list.size()+" aguardando</span>":link("/aguardando","Ver todos","btn btn-quiet");
        StringBuilder b=new StringBuilder(heading("Equipe presente",title,copy,action));
        b.append("<section class='panel fade-in delay-1'>");
        if(list.isEmpty()){b.append("<div class='empty-state'><strong>").append(filter==null?"Fila limpa":"Nenhum colaborador disponível para "+e(filter.name)).append("</strong><p>").append(filter==null?"Ninguém presente está sem posto.":"Nenhuma pessoa aguardando possui a habilitação necessária neste momento.").append("</p></div>");}
        else{b.append("<div class='table-wrap'><table class='data-table'><thead><tr><th>Colaborador</th><th>Matrícula</th><th>Cargo</th><th>Habilidades registradas</th><th></th></tr></thead><tbody>");for(Employee x:list){b.append("<tr><td><div class='employee-cell'>").append(avatar(x.name)).append("<div><div class='employee-fullname'>").append(e(x.name)).append("</div><div class='employee-id'>Chegada: ").append(e(nvl(x.arrivalTime,"—"))).append("</div></div></div></td><td class='mono'>").append(e(x.registration)).append("</td><td>").append(e(x.role)).append("</td><td><div class='skill-list'>");for(String sk:x.skills)b.append("<span class='skill'>").append(e(sk)).append("</span>");b.append("</div></td><td>").append(link("/alocar?id="+u(x.id),"Alocar →","btn btn-primary")).append("</td></tr>");}b.append("</tbody></table></div>");}b.append("</section>");
        return shell("Aguardando",b.toString(),"/aguardando");
    }

    String allocation(String employeeId) {
        Employee x=service.employee(employeeId);if(x==null)return shell("Alocação",heading("Alocação","Colaborador não encontrado","Esta ficha não está disponível na operação.",link("/aguardando","← Voltar","btn btn-quiet")),"/aguardando");
        Map<String,Integer> counts=service.counts(), projected=service.projectedCounts();
        boolean already=service.state().pending.stream().anyMatch(p->p.employeeId.equals(x.id));
        StringBuilder b=new StringBuilder(heading("Alocar colaborador","Escolha um posto seguro.","A seleção fica pendente para revisão. Nada muda na operação até a confirmação.",link("/aguardando","← Voltar","btn btn-quiet")));
        b.append("<div class='allocation-layout fade-in delay-1'><section class='profile-card'><div class='profile-avatar'>").append(initials(x.name)).append("</div><div class='profile-name'>").append(e(x.name)).append("</div><div class='profile-role'>").append(e(x.role)).append("</div><div class='profile-id'>MATRÍCULA ").append(e(x.registration)).append("</div><div class='profile-section'><div class='small-label'>Habilidades e treinamentos</div><div class='training-list'>");for(String sk:x.skills)b.append("<div class='training'>✓ ").append(e(sk)).append("</div>");b.append("</div></div><div class='profile-section'><div class='small-label'>Estado atual</div><div style='margin-top:10px'><span class='status-pill neutral'>AGUARDANDO POSTO</span></div></div></section>");
        b.append("<section class='allocation-panel'><h2>Postos disponíveis</h2><p class='allocation-help'>Compatibilidade e capacidade são verificadas pelo servidor antes de aceitar a escolha.</p><form method='post' action='/acao/alocar'><input type='hidden' name='employeeId' value='").append(a(x.id)).append("'><div class='post-options'>");
        int idx=0;for(Post p:service.posts()){boolean compatible=x.skills.contains(p.name);boolean capacity=projected.get(p.id)<p.maximum;boolean selectable=compatible&&capacity&&!already;String reason=!compatible?(p.requirement!=null?p.requirement+" não registrado.":"Cargo não habilitado."):!capacity?"Capacidade máxima atingida.":already?"Este colaborador já possui alteração pendente.":"";b.append("<label class='post-option ").append(selectable?"":"disabled").append("'><span class='post-icon'>").append(postSymbol(p.id)).append("</span><span class='post-option-copy'><span class='post-option-title'>").append(e(p.name)).append("</span><span class='post-option-meta'>").append(projected.get(p.id)).append("/").append(p.maximum).append(" projetados · ").append(counts.get(p.id)).append("/").append(p.planned).append(" atual/planejado · mínimo ").append(p.minimum);if(p.requirement!=null)b.append(" · exige ").append(e(p.requirement));b.append("</span>");if(!selectable)b.append("<span class='post-option-reason'>").append(e(reason)).append("</span>");b.append("</span><input class='post-radio' type='radio' name='postId' value='").append(a(p.id)).append("' ").append(selectable?"":"disabled").append("></label>");idx++;}
        b.append("</div><div class='pending-note'>◷ <span>A escolha será adicionada à revisão. O posto só muda após confirmar todas as alterações.</span></div><div class='allocation-actions'>").append(link("/aguardando","Cancelar","btn btn-quiet")).append("<button class='btn btn-primary' type='submit' ").append(already?"disabled":"").append(">Adicionar à revisão →</button></div></form></section></div>");
        return shell("Alocar",b.toString(),"/aguardando");
    }

    String pending() {
        AppState s=service.state();Map<String,Integer> before=service.counts(),after=service.projectedCounts();
        String action=s.pending.isEmpty()?"":"<form method='post' action='/acao/descartar' class='inline-form'><button class='btn btn-danger' type='submit'>Descartar tudo</button></form>";
        StringBuilder b=new StringBuilder(heading("Revisão operacional","Alterações pendentes","Confira cada mudança antes de publicar. A operação atual permanece intacta enquanto esta lista estiver aberta.",action));
        if(s.pending.isEmpty())b.append("<section class='panel fade-in'><div class='empty-state'><strong>Nenhuma alteração pendente</strong><p>As escolhas feitas pela equipe aparecerão aqui para revisão antes de aplicar.</p>").append(link("/aguardando","Ir para aguardando →","btn btn-primary")).append("</div></section>");
        else{b.append("<div class='review-layout fade-in delay-1'><section class='pending-list'>");for(Pending p:s.pending){Employee x=service.employee(p.employeeId);Post post=service.post(p.postId);if(x==null||post==null)continue;b.append("<div class='pending-item'><div><div class='pending-person'>").append(avatar(x.name)).append("<div><div class='pending-title'>").append(e(x.name)).append("</div><div class='pending-detail'>").append(e(x.registration)).append(" · ").append(e(x.role)).append("</div></div></div><div class='impact'><strong>").append(p.kind==PendingKind.REMOVE?"RETIRADA":"NOVA ALOCAÇÃO").append("</strong><span>→</span><strong>").append(e(post.name)).append("</strong><span>· escolha às ").append(e(p.createdAt)).append("</span></div></div><form method='post' action='/acao/remover-pendente'><input type='hidden' name='id' value='").append(a(p.id)).append("'><button class='btn btn-quiet'>Remover</button></form></div>");}b.append("</section><aside class='review-summary'><h2>Impacto da aplicação</h2><p class='heading-copy small-copy'>Antes → depois por posto afetado</p>");for(Post post:service.posts()){if(s.pending.stream().noneMatch(p->p.postId.equals(post.id)))continue;int bc=before.get(post.id),ac=after.get(post.id);b.append("<div class='summary-row'><span>").append(e(post.name)).append("<br>").append(statusPill(service.statusFor(bc,post))).append(" → ").append(statusPill(service.statusFor(ac,post))).append("</span><strong>").append(bc).append("/").append(post.planned).append(" → ").append(ac).append("/").append(post.planned).append("</strong></div>");}b.append("<div class='confirm-box'><strong>").append(s.pending.size()).append(" alteração(ões)</strong> pronta(s). A publicação atualiza o Painel TV e registra o histórico.</div><div class='review-actions'><form method='post' action='/acao/confirmar'><button class='btn btn-primary full'>✓ Confirmar e aplicar</button></form>").append(link("/aguardando","Adicionar outra pessoa","btn btn-quiet")).append("</div></aside></div>");}
        return shell("Pendentes",b.toString(),"/pendentes");
    }

    String confirmation() {
        AppState s=service.state();Map<String,Integer> counts=service.counts();StringBuilder b=new StringBuilder(heading("Aplicação concluída","Turno atualizado com segurança.","As alterações foram publicadas. A equipe já pode consultar o novo desenho no Painel TV.",""));
        b.append("<section class='confirmation-card fade-in delay-1'><div class='success-mark'>✓</div><h2>Alterações aplicadas</h2><p>O status dos postos foi recalculado e os registros foram gravados no histórico da operação.</p><div class='result-list'>");for(ConfirmedChange ch:s.lastConfirmed){Employee x=service.employee(ch.employeeId);Post p=service.post(ch.postId);if(x!=null&&p!=null)b.append("<div class='result-item'><strong>").append(e(x.name)).append("</strong><span>").append(ch.kind==PendingKind.REMOVE?"Retirada do posto":"Alocação aplicada").append(" · ").append(e(p.name)).append(" · ").append(e(ch.time)).append("</span></div>");}b.append("</div>");List<Post> released=new ArrayList<>();for(Post p:service.posts())if(s.lastConfirmed.stream().anyMatch(ch->ch.postId.equals(p.id)&&"critical".equals(service.statusFor(ch.beforeCount,p))&&!"critical".equals(service.statusFor(ch.afterCount,p))))released.add(p);if(!released.isEmpty()){b.append("<div class='confirm-box left'><strong>Postos que deixaram o estado crítico</strong>");for(Post p:released)b.append("<div class='release-row'>✓ ").append(e(p.name)).append(" · ").append(counts.get(p.id)).append("/").append(p.minimum).append(" mínimo</div>");b.append("</div>");}b.append(link("/","Voltar ao Dashboard →","btn btn-primary full top-gap")).append("</section>");return shell("Confirmação",b.toString(),"/pendentes");
    }

    String posts(String view) {
        Map<String,Integer> c=service.counts();boolean map="map".equalsIgnoreCase(view);
        String toggle="<div class='view-toggle'>"+link("/postos?view=list","☷ Lista","toggle-option "+(!map?"active":""))+link("/postos?view=map","▦ Mapa","toggle-option "+(map?"active":""))+"</div>";
        StringBuilder b=new StringBuilder(heading("Desenho da operação","Postos do setor","Acompanhe a ocupação real, o planejado e os limites de cada ponto da linha.",toggle));
        if(map){b.append("<section class='panel fade-in delay-1'><div class='map-board'>");int i=1;for(Post p:service.posts()){String st=service.statusFor(c.get(p.id),p);b.append("<div class='map-post ").append(p.id).append(" ").append(st).append("'><div class='map-tag'>POSTO 0").append(i++).append("</div><strong>").append(e(p.name)).append("</strong><div><div class='map-count'>").append(c.get(p.id)).append("<span class='map-plan'>/").append(p.planned).append("</span></div>").append(statusPill(st)).append("</div></div>");}b.append("</div></section>");}
        else{b.append("<section class='panel fade-in delay-1'><div class='table-wrap'><table class='data-table'><thead><tr><th>Posto</th><th>Atual / planejado</th><th>Mínimo</th><th>Máximo</th><th>Equipe atual</th><th>Status</th></tr></thead><tbody>");for(Post p:service.posts()){List<Employee> assigned=service.assigned(p.id);b.append("<tr><td><div class='employee-cell'><span class='post-icon'>").append(postSymbol(p.id)).append("</span><div><div class='employee-fullname'>").append(e(p.name)).append("</div><div class='employee-id'>").append(p.requirement==null?"Sem requisito específico":"Requer "+e(p.requirement)).append("</div></div></div></td><td class='mono bold'>").append(c.get(p.id)).append(" / ").append(p.planned).append("</td><td class='mono'>").append(p.minimum).append("</td><td class='mono'>").append(p.maximum).append("</td><td><div class='assigned-list'>");if(assigned.isEmpty())b.append("<span class='employee-id'>Nenhum colaborador</span>");for(Employee x:assigned){boolean removalPending=service.state().pending.stream().anyMatch(z->z.employeeId.equals(x.id));b.append("<div class='assigned-person'><span class='assigned-person-name'>").append(avatar(x.name)).append("<span>").append(e(x.name)).append("</span></span><form method='post' action='/acao/retirar-posto'><input type='hidden' name='employeeId' value='").append(a(x.id)).append("'><input type='hidden' name='postId' value='").append(a(p.id)).append("'><button class='btn btn-danger btn-small' ").append(removalPending?"disabled":"").append(">").append(removalPending?"Pendente":"Retirar").append("</button></form></div>");}b.append("</div></td><td>").append(statusPill(service.statusFor(c.get(p.id),p))).append("</td></tr>");}b.append("</tbody></table></div></section>");}
        return shell("Postos",b.toString(),"/postos");
    }

    String history() {
        AppState s=service.state();StringBuilder b=new StringBuilder(heading("Rastreabilidade","Histórico da operação","Um registro simples das decisões aplicadas neste turno, com horário e responsável.",""));b.append("<section class='panel fade-in delay-1'>");if(s.history.isEmpty())b.append("<div class='empty-state'><strong>Histórico vazio</strong><p>Depois de confirmar uma alocação, o horário, o posto e o responsável aparecerão nesta linha do tempo.</p>").append(link("/aguardando","Fazer uma alocação","btn btn-primary")).append("</div>");else{b.append("<div class='table-wrap'><table class='data-table history-table'><thead><tr><th>Horário</th><th>Colaborador</th><th>Ação</th><th>Posto</th><th>Responsável</th></tr></thead><tbody>");List<HistoryEntry> rev=new ArrayList<>(s.history);Collections.reverse(rev);for(HistoryEntry h:rev){Employee x=service.employee(h.employeeId);Post p=service.post(h.postId);b.append("<tr><td class='mono'>").append(e(h.time)).append("</td><td><div class='employee-cell'>").append(avatar(x==null?"?":x.name)).append("<span class='employee-fullname'>").append(e(x==null?"Desconhecido":x.name)).append("</span></div></td><td><span class='action-chip'>").append(e(h.action)).append("</span></td><td>").append(e(p==null?"—":p.name)).append("</td><td class='employee-id'>").append(e(h.responsible)).append("</td></tr>");}b.append("</tbody></table></div>");}b.append("</section>");return shell("Histórico",b.toString(),"/historico");
    }

    String tv() {
        AppState s=service.state();List<Employee> allocated=s.employees.stream().filter(x->x.status==EmployeeStatus.ALLOCATED).toList();StringBuilder b=new StringBuilder("<!doctype html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta http-equiv='refresh' content='30'><title>Painel TV · ALOC.OP</title><link rel='stylesheet' href='/styles.css'></head><body><div class='tv-page'><header class='tv-head'><div><div class='tv-kicker'>PAINEL DE PRODUÇÃO · SETOR FATIADO</div><div class='tv-title'>FATIADO — TURNO ").append(e(s.shift.label().toUpperCase())).append("</div></div><div><div class='tv-clock' id='clock'>--:--</div><div class='tv-updated'>última atualização operacional · ").append(e(s.lastUpdated)).append("</div></div></header><section class='tv-table-shell'><table class='tv-table'><thead><tr><th>Colaborador</th><th>Matrícula</th><th>Posto atual</th></tr></thead><tbody>");for(Employee x:allocated){Post p=service.post(x.postId);b.append("<tr><td>").append(e(shortName(x.name))).append("</td><td class='tv-id'>").append(e(x.registration)).append("</td><td class='tv-post'>").append(e(p==null?"—":p.name)).append("</td></tr>");}b.append("</tbody></table></section><footer class='tv-footer'><span><span class='live-dot inline-dot'></span> operação ao vivo</span><span>").append(allocated.size()).append(" colaboradores alocados · Fatiado</span></footer></div><script>function tick(){document.getElementById('clock').textContent=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});}tick();setInterval(tick,10000);</script></body></html>");return b.toString();
    }

    private String shell(String title,String body,String current){AppState s=service.state();int waiting=service.waiting(null).size(),pending=s.pending.size();return "<!doctype html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>"+e(title)+" · ALOC.OP</title><link rel='stylesheet' href='/styles.css'></head><body><div class='app-frame'><aside class='sidebar'><a href='/' class='brand'><span class='brand-mark'>▦</span><span><span class='brand-name'>ALOC.OP</span><span class='brand-sub'>cockpit operacional · JAVA</span></span></a><div class='nav-label'>Operação</div><nav class='nav-group'>"+nav("/","Dashboard","▦",current,0)+nav("/aguardando","Aguardando","◎",current,waiting)+nav("/postos","Postos","▤",current,0)+nav("/historico","Histórico","↺",current,0)+"</nav><div class='nav-label nav-gap'>Revisão</div><nav class='nav-group'>"+nav("/pendentes","Pendentes","◇",current,pending)+"<a href='/tv' target='_blank' class='nav-item'><span class='nav-symbol'>▣</span><span>Painel TV</span></a></nav><div class='shift-card'><div class='shift-overline'>Turno em curso</div><div class='shift-title'>Fatiado — Turno "+e(s.shift.label())+"</div><div class='shift-live'><span class='live-dot'></span> Operação ao vivo</div><form method='post' action='/acao/restaurar' onsubmit=\"return confirm('Restaurar a demonstração? O histórico e as alterações serão apagados.');\"><button class='restore-link' type='submit'>↻ Restaurar demonstração</button></form></div></aside><main class='main-shell'><header class='topbar'><div class='crumb'><strong>FATIADO</strong><span> / </span> TURNO "+e(s.shift.label().toUpperCase())+"</div><div class='top-actions'><div class='updated'>◷ Atualizado às "+e(s.lastUpdated)+"</div>"+avatar("Responsável")+"</div></header><div class='page'>"+body+"</div><nav class='bottom-nav'>"+bottom("/","Dashboard","▦",current)+bottom("/aguardando","Aguardando","◎",current)+bottom("/postos","Postos","▤",current)+bottom("/historico","Histórico","↺",current)+"</nav></main></div></body></html>";}
    private String shiftSelector(){AppState s=service.state();StringBuilder b=new StringBuilder("<form method='post' action='/acao/turno' class='shift-selector'><span class='shift-selector-label'>Turno</span><select name='shift' onchange='this.form.submit()'>");for(ShiftName sh:ShiftName.values())b.append("<option value='").append(a(sh.label())).append("' ").append(sh==s.shift?"selected":"").append(">").append(e(sh.label())).append("</option>");return b.append("</select></form>").toString();}
    private String heading(String eyebrow,String title,String copy,String action){return "<div class='page-heading fade-in'><div><div class='eyebrow'>"+e(eyebrow)+"</div><h1>"+e(title)+"</h1>"+(copy==null||copy.isBlank()?"":"<p class='heading-copy'>"+e(copy)+"</p>")+"</div>"+(action==null?"":action)+"</div>";}
    private String metric(String label,String value,String note,String clazz){return "<div class='metric "+clazz+"'><div class='metric-label'>"+e(label)+"</div><div class='metric-value'>"+value+"</div><div class='metric-note'>"+e(note)+"</div></div>";}
    private String personCard(Employee x){return "<div class='person-card'><div class='person-top'><span class='person-initial'>"+initials(x.name)+"</span><span class='status-pill neutral'>PRESENTE</span></div><div class='person-name'>"+e(x.name)+"</div><div class='person-role'>"+e(x.role)+"</div>"+link("/alocar?id="+u(x.id),"Alocar →","btn btn-primary")+"</div>";}
    private String statusPill(String status){return "<span class='status-pill "+a(status)+"'>"+e(service.statusLabel(status))+"</span>";}
    private String avatar(String name){return "<span class='avatar'>"+initials(name)+"</span>";}
    private String nav(String href,String label,String symbol,String current,int count){return "<a href='"+a(href)+"' class='nav-item "+(current.equals(href)?"active":"")+"'><span class='nav-symbol'>"+symbol+"</span><span>"+e(label)+"</span>"+(count>0?"<span class='nav-count'>"+count+"</span>":"")+"</a>";}
    private String bottom(String href,String label,String symbol,String current){return "<a href='"+a(href)+"' class='bottom-item "+(current.equals(href)?"active":"")+"'><span>"+symbol+"</span><span>"+e(label)+"</span></a>";}
    private String link(String href,String label,String clazz){return "<a href='"+a(href)+"' class='"+a(clazz)+"'>"+e(label)+"</a>";}
    private static String initials(String name){if(name==null||name.isBlank())return "?";String[] p=name.trim().split("\\s+");return ((p[0].substring(0,1))+(p.length>1?p[1].substring(0,1):"")).toUpperCase();}
    private static String shortName(String name){String[] p=name.trim().split("\\s+");return p.length>1?p[0]+" "+p[1].substring(0,1)+".":name;}
    private static String postSymbol(String id){return switch(id){case "machine"->"⚙";case "conveyor"->"▦";case "pallet"->"▣";default->"▤";};}
    private static String nvl(String s,String fallback){return s==null?fallback:s;}
    static String e(String s){if(s==null)return "";return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
    static String a(String s){return e(s);}
    static String u(String s){try{return java.net.URLEncoder.encode(s,java.nio.charset.StandardCharsets.UTF_8);}catch(Exception ex){return s;}}
}
